const $=id=>document.getElementById(id);
const copy={
en:{subtitle:"Entry flow · Design draft",platform:"Platform",language:"Language",home:"Home",connect:"Start a connection",share:"Accept connections",settings:"Settings",back:"Back",question:"How would you like to use it?",connectHint:"Choose a device to connect to and control.",shareHint:"Let another device connect to and control your current screen.",add:"Add target",devices:"Devices",refresh:"Refresh devices",remembered:"Remembered",first:"First connection",online:"Available",offline:"Offline",emptyTitle:"No devices or connection history",emptyHint:"Start accepting connections on the other device, or use Add target to enter its IP.",off:"Not accepting connections",on:"Waiting for a connection",name:"This device’s name",changeName:"Change",localIp:"This device’s IP",password:"Current password",changePassword:"Change password",passwordHint:"Use the password below to connect to this device.",show:"Show",hide:"Hide",copy:"Copy",start:"Start accepting connections",stop:"Stop accepting connections",targetIp:"Target IP",targetPassword:"Pairing password",remember:"Remember password",cancel:"Cancel",save:"Save",generate:"Generate",newPassword:"New password",passwordHelp:"8 characters, no spaces.",saveHelp:"Saving stops accepting connections and disconnects the current device.",invalidPassword:"Use exactly 8 characters without spaces.",invalidIp:"Enter a valid private IPv4 address.",pairError:"The pairing password did not match.",defaultState:"Default",noDevices:"No devices",permissions:"Permissions needed",permissionHint:"Allow screen recording and input control before accepting connections.",permissionAction:"Review permissions",note:"Design preview only. Devices and passwords are fictional; no connections, clipboard access, saved credentials or system changes.",spec:"Design notes",previewCopy:"Preview: copied.",previewConnect:"Preview: connection completed. The native app would now show the remote desktop.",previewRefresh:"Preview: device list refreshed.",previewPermission:"Preview: the native app would open macOS permission settings.",reconnect:"Reconnect automatically",quality:"Default picture quality",standard:"Standard",clipboard:"Clipboard",text:"Sync text",files:"Sync files",connection:"Connection",general:"General",nameTitle:"Change this device’s name",systemName:"Use system name",close:"Close",modalConnect:"Connect to device",conflictTitle:"Stop accepting connections?",conflictHint:"This ends any current connection to this device.",stopAndConnect:"Stop & connect",about:"About"},
zh:{subtitle:"入口与操作流程 · 设计草图",platform:"平台",language:"语言",home:"首页",connect:"发起连接",share:"接受连接",settings:"设置",back:"返回",question:"你想如何使用？",connectHint:"选择你要连接并操作的设备。",shareHint:"让另一台设备连接并操作你的当前屏幕。",add:"添加目标",devices:"设备",refresh:"刷新设备",remembered:"已记住",first:"首次连接",online:"可连接",offline:"离线",emptyTitle:"暂无设备或连接记录",emptyHint:"请让对方设备开始接受连接，或通过“添加目标”输入目标 IP。",off:"尚未接受连接",on:"等待连接",name:"本机名称",changeName:"修改",localIp:"本机 IP",password:"当前密码",changePassword:"修改密码",passwordHint:"连接本设备时，使用下方密码。",show:"查看",hide:"隐藏",copy:"复制",start:"开始接受连接",stop:"停止接受连接",targetIp:"目标 IP",targetPassword:"配对密码",remember:"记住密码",cancel:"取消",save:"保存",generate:"自动生成",newPassword:"新密码",passwordHelp:"8 位，不含空格。",saveHelp:"保存后将停止接受连接，并断开当前连接。",invalidPassword:"请输入 8 位密码，不含空格。",invalidIp:"请输入有效的私有 IPv4 地址。",pairError:"配对密码不正确。",defaultState:"默认",noDevices:"空列表",permissions:"待授权",permissionHint:"接受连接前，需要授权屏幕录制和辅助功能。",permissionAction:"检查权限",note:"仅为设计预览。设备和密码均为虚构示例，不实际连接、不操作剪贴板、不保存凭据、不修改系统。",spec:"设计说明",previewCopy:"预览：已模拟复制。",previewConnect:"预览：已模拟连接成功，实际客户端将进入远程桌面。",previewRefresh:"预览：已模拟刷新设备列表。",previewPermission:"预览：实际客户端将打开 macOS 权限设置。",reconnect:"自动重连",quality:"默认画质",standard:"标准",clipboard:"剪贴板",text:"同步文字",files:"同步文件",connection:"连接设置",general:"通用",nameTitle:"修改本机名称",systemName:"使用系统名称",close:"关闭",modalConnect:"连接设备",conflictTitle:"停止接受连接？",conflictHint:"这将断开其他设备对本设备的当前连接。",stopAndConnect:"停止接受并连接",about:"关于"}
};
const paths={gear:'<path d="m9 3 1-1h4l1 1 1 3 3 1 2 1v4l-2 1-3 1-1 3-1 1h-4l-1-1-1-3-3-1-2-1V8l2-1 3-1Z"/><circle cx="12" cy="10" r="3"/>',back:'<path d="m14 5-7 7 7 7"/>',monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M9 21h6m-3-4v4"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M18 18A8 8 0 0 1 5 15"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let lang=new URLSearchParams(location.search).get('lang')==='zh'?'zh':'en',platform='windows',page='home',empty=false,permissionMissing=false,sharing=false,revealed=false,password='Blue482X',modal=null,returnFocus=null;
const names={windows:'Desk PC',mac:'My MacBook'}; let localNames={...names};
const t=key=>copy[lang][key];
function chrome(){return platform==='mac'?`<span class="traffic" aria-hidden="true"><i></i><i></i><i></i></span><span>Local Remote Desktop</span>`:`<img src="../../assets/brand/icon.svg" alt=""><span>Local Remote Desktop</span><span class="window-buttons" aria-hidden="true"><span>−</span><span>□</span><span>×</span></span>`;}
const settingsButton=()=>`<button class="icon-button" data-action="settings" aria-label="${t('settings')}">${icon('gear')}</button>`;
const back=()=>`<button class="back" data-action="home">${icon('back')}${t('back')}</button>`;
function home(){return `<div class="topline"><span></span>${settingsButton()}</div><h2 class="welcome-heading">${t('question')}</h2><div class="choices"><button class="choice" data-action="connect"><img class="role-illustration" src="initiate-connection.svg" alt="" draggable="false"><strong>${t('connect')}</strong></button><button class="choice" data-action="share"><img class="role-illustration" src="accept-connection.svg" alt="" draggable="false"><strong>${t('share')}</strong></button></div>`;}
function device(name,os,status,address){return `<button class="device" data-action="device" data-address="${address}" data-name="${name}" data-os="${os}" ${status==='offline'?'disabled':''}><span class="device-icon">${icon('monitor')}</span><span class="device-info"><strong>${name}</strong><small>${os} · ${t(status==='first'?'first':'remembered')}</small></span><span class="device-status ${status==='offline'?'offline':''}"><i class="dot"></i>${t(status==='offline'?'offline':'online')}</span></button>`;}
function connect(){return `<div class="topline">${back()}${settingsButton()}</div><h2 class="heading">${t('connect')}</h2><p class="description">${t('connectHint')}</p><div class="section-title"><h3>${t('devices')}</h3><div style="display:flex;gap:5px"><button class="icon-button" data-action="refresh" aria-label="${t('refresh')}">${icon('refresh')}</button><button data-action="add">＋ ${t('add')}</button></div></div>${empty?`<div class="empty">${icon('monitor')}<strong>${t('emptyTitle')}</strong><p>${t('emptyHint')}</p></div>`:`<div class="device-list">${device('Studio Mac','macOS','remembered','192.168.1.24')}${device('Office PC','Windows','first','192.168.1.70')}${device('Travel Mac','macOS','offline','192.168.1.35')}</div>`}`;}
function share(){return `<div class="topline">${back()}${settingsButton()}</div><h2 class="heading">${t('share')}</h2><p class="description">${t('shareHint')}</p><div class="sharing"><div class="status ${sharing?'active':''}"><i class="dot"></i>${t(sharing?'on':'off')}</div><div class="form-row"><div class="field-info"><span class="field-label">${t('name')}</span><span class="field-value">${esc(localNames[platform])}</span></div><button class="small" data-action="name">${t('changeName')}</button></div><div class="form-row"><div class="field-info"><span class="field-label">${t('localIp')}</span><span class="field-value">192.168.1.${platform==='mac'?'12':'10'}</span></div><button class="small" data-action="copy">${t('copy')}</button></div><div class="rule"></div><p class="password-hint">${t('passwordHint')}</p><div class="password-heading"><strong>${t('password')}</strong><button class="small" data-action="password">${t('changePassword')}</button></div><div class="password-row"><span class="password">${revealed?esc(password):'••••••••'}</span><button class="small" data-action="reveal">${t(revealed?'hide':'show')}</button><button class="small" data-action="copy">${t('copy')}</button></div></div>${permissionMissing&&platform==='mac'?`<div class="permission"><p>${t('permissionHint')}</p><button data-action="permission">${t('permissionAction')}</button></div>`:''}<div class="footer-action"><button class="${sharing?'stop':'primary'}" data-action="sharing">${t(sharing?'stop':'start')}</button></div>`;}
function notify(key){$('feedback').textContent=t(key);}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('language').value=lang;$('app').classList.toggle('mac',platform==='mac');$('review-subtitle').textContent=t('subtitle');$('platform-label').textContent=t('platform');$('language-label').textContent=t('language');$('review-note').textContent=t('note');$('spec-link').textContent=t('spec');$('spec-link').href=lang==='zh'?'../../docs/zh-CN/entry-design.md':'../../docs/entry-design.md';$('pages').innerHTML=['home','connect','share'].map(p=>`<button data-page="${p}" ${p===page?'aria-current="page"':''}>${t(p)}</button>`).join('');$('chrome').innerHTML=chrome();$('content').classList.toggle('home-page',page==='home');$('content').innerHTML=page==='home'?home():page==='connect'?connect():share();$('scenarios').innerHTML=page==='home'?'':page==='connect'?`<button data-scenario="devices" class="${!empty?'selected':''}">${t('defaultState')}</button><button data-scenario="empty" class="${empty?'selected':''}">${t('noDevices')}</button>`:platform==='mac'?`<button data-scenario="ready" class="${!permissionMissing?'selected':''}">${t('defaultState')}</button><button data-scenario="permission" class="${permissionMissing?'selected':''}">${t('permissions')}</button>`:'';renderModal();}
function openModal(kind,peer=null){returnFocus=document.activeElement;modal={kind,peer};renderModal();const field=$('modal-layer').querySelector('input:not([type=checkbox]),select');(field||$('modal-layer').querySelector('button')).focus();}
function closeModal(){modal=null;renderModal();if(returnFocus?.isConnected)returnFocus.focus();else $('content').querySelector('button')?.focus();}
function renderModal(){const layer=$('modal-layer');if(!modal){layer.innerHTML='';return;}let title='',body='';const kind=modal.kind;
if(kind==='target'){title=modal.peer?modal.peer.name:t('add');body=`${modal.peer?`<p class="help">${esc(modal.peer.os)} · ${esc(modal.peer.address)}</p>`:`<label class="block" for="target-ip">${t('targetIp')}</label><input id="target-ip" type="text" inputmode="decimal" placeholder="192.168.1.24" autocomplete="off">`}<label class="block" for="target-password">${t('targetPassword')}</label><input id="target-password" type="password" autocomplete="off" value="${modal.peer?.address==='192.168.1.24'?'Blue482X':''}"><label class="remember"><input type="checkbox" checked>${t('remember')}</label><p class="error" id="form-error" role="alert"></p>`;}
if(kind==='password'){title=t('changePassword');body=`<label class="block" for="new-password">${t('newPassword')}</label><div class="generate-row"><input id="new-password" type="text" maxlength="8" autocomplete="off"><button class="generate" data-action="generate">${t('generate')}</button></div><p class="help">${t('passwordHelp')}</p>${sharing?`<p class="help">${t('saveHelp')}</p>`:''}<p class="error" id="form-error" role="alert"></p>`;}
if(kind==='name'){title=t('nameTitle');body=`<label class="block" for="local-name">${t('name')}</label><input id="local-name" type="text" maxlength="64" value="${esc(localNames[platform])}"><p><button class="small" data-action="system-name">${t('systemName')}</button></p><p class="error" id="form-error" role="alert"></p>`;}
if(kind==='conflict'){title=t('conflictTitle');body=`<p class="help">${t('conflictHint')}</p>`;}
if(kind==='settings'){title=t('settings');body=`<div class="settings-list"><section class="settings-group"><h3>${t('general')}</h3><label class="block" for="settings-language">${t('language')}</label><select id="settings-language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="zh" ${lang==='zh'?'selected':''}>简体中文</option></select></section><section class="settings-group"><h3>${t('connection')}</h3><label>${t('quality')} <select><option>${t('standard')}</option></select></label><label class="remember"><input type="checkbox" checked>${t('reconnect')}</label></section><section class="settings-group"><h3>${t('clipboard')}</h3><label class="remember"><input type="checkbox" checked>${t('text')}</label><label class="remember"><input type="checkbox" checked>${t('files')}</label></section><section class="settings-group"><h3>${t('about')}</h3><p>Local Remote Desktop</p><p>GPL-3.0-or-later</p></section></div>`;}
layer.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('close')}">${icon('close')}</button></div>${body}<div class="dialog-actions">${kind==='settings'?`<button data-action="close">${t('close')}</button>`:`<button data-action="close">${t('cancel')}</button><button class="primary" data-action="submit">${t(kind==='target'?'connect':kind==='conflict'?'stopAndConnect':'save')}</button>`}</div></section>`;}
function submit(){const kind=modal.kind;if(kind==='target'){const address=modal.peer?.address||$('target-ip').value.trim(),parts=address.split('.');const nums=parts.map(Number);const valid=parts.length===4&&parts.every(x=>/^\d{1,3}$/.test(x))&&nums.every(x=>x>=0&&x<=255)&&(nums[0]===10||nums[0]===192&&nums[1]===168||nums[0]===172&&nums[1]>=16&&nums[1]<=31);if(!valid){$('form-error').textContent=t('invalidIp');return;}if($('target-password').value!=='Blue482X'){$('form-error').textContent=t('pairError');return;}if(sharing){modal={kind:'conflict'};renderModal();$('modal-layer').querySelector('button').focus();return;}closeModal();notify('previewConnect');return;}if(kind==='conflict'){sharing=false;closeModal();render();notify('previewConnect');return;}if(kind==='password'){const draft=$('new-password').value;if(draft.length!==8||/\s/.test(draft)){$('form-error').textContent=t('invalidPassword');return;}password=draft;sharing=false;revealed=false;}if(kind==='name'){const draft=$('local-name').value.trim();if(!draft){$('local-name').focus();return;}localNames[platform]=draft;}closeModal();render();}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;const a=button.dataset.action;if(button.dataset.page){page=button.dataset.page;modal=null;render();return;}if(button.dataset.scenario){const scenario=button.dataset.scenario;empty=scenario==='empty';permissionMissing=scenario==='permission';if(permissionMissing)sharing=false;render();return;}if(['home','connect','share'].includes(a)){page=a;modal=null;render();}else if(a==='settings')openModal('settings');else if(a==='add')openModal('target');else if(a==='device')openModal('target',{address:button.dataset.address,name:button.dataset.name,os:button.dataset.os});else if(a==='password'||a==='name')openModal(a);else if(a==='close')closeModal();else if(a==='submit')submit();else if(a==='generate'){$('new-password').value='Lime482Q';$('new-password').focus();}else if(a==='system-name')$('local-name').value=names[platform];else if(a==='reveal'){revealed=!revealed;render();}else if(a==='sharing'){if(permissionMissing&&platform==='mac'){notify('previewPermission');return;}sharing=!sharing;render();}else if(a==='copy')notify('previewCopy');else if(a==='refresh')notify('previewRefresh');else if(a==='permission')notify('previewPermission');});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}else if(e.key==='Enter'&&modal.kind!=='settings'&&e.target.tagName==='INPUT'){e.preventDefault();submit();}else if(e.key==='Tab'){const nodes=[...$('modal-layer').querySelectorAll('button,input,select')].filter(x=>!x.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
$('platform').addEventListener('change',e=>{platform=e.target.value;modal=null;sharing=false;permissionMissing=false;render();});$('language').addEventListener('change',e=>{lang=e.target.value;render();});document.addEventListener('change',e=>{if(e.target.id==='settings-language'){lang=e.target.value;render();$('settings-language')?.focus();}});render();
